import { memo, type ComponentPropsWithoutRef, type FC } from "react"
import {
  ComposerPrimitive,
  unstable_defaultDirectiveFormatter,
  unstable_useTriggerPopoverScopeContext,
  type Unstable_DirectiveFormatter,
  type Unstable_TriggerItem,
} from "@assistant-ui/react"
import { cn } from "cn"

import {
  ChevronLeftIcon,
  ChevronRightIcon,
  SparklesIcon,
} from "@/components/assistant-ui/elements/aui-icons"

type IconComponent = FC<{ className?: string }>

type DirectiveBehaviorProps = {
  /** Formatter used to serialize the selected item into composer text. */
  formatter?: Unstable_DirectiveFormatter | undefined
  /** Called after the directive text has been inserted into the composer. */
  onInserted?: ((item: Unstable_TriggerItem) => void) | undefined
}

type ActionBehaviorProps = {
  /** Formatter used to serialize the audit-trail chip (when `removeOnExecute` is false). */
  formatter?: Unstable_DirectiveFormatter | undefined
  /** Invoked with the selected item at the moment of selection. */
  onExecute: (item: Unstable_TriggerItem) => void
  /** If `true`, strip the trigger text from the composer after executing. @default false */
  removeOnExecute?: boolean | undefined
}

type ComposerTriggerPopoverBaseProps = Omit<
  ComponentPropsWithoutRef<typeof ComposerPrimitive.Unstable_TriggerPopover>,
  "children"
> & {
  /**
   * Maps icon keys to components. Items look up via `item.metadata?.icon`
   * (string); categories look up via their `id`.
   */
  iconMap?: Record<string, IconComponent>
  /** Fallback icon when no entry in `iconMap` matches. */
  fallbackIcon?: IconComponent
  /** Label shown on the back button. @default "Back" */
  backLabel?: string
  /** Label shown when no categories are available. @default "No items available" */
  emptyCategoriesLabel?: string
  /** Label shown when no items match. @default "No matching items" */
  emptyItemsLabel?: string
  /** Label shown while an async adapter is resolving items. @default "Loading…" */
  loadingLabel?: string
}

type ComposerTriggerPopoverProps = ComposerTriggerPopoverBaseProps &
  (
    | {
        /** Insert-directive behavior. */
        directive: DirectiveBehaviorProps
        action?: never
      }
    | {
        /** Action behavior. */
        action: ActionBehaviorProps
        directive?: never
      }
  )

function resolveIcon(
  iconKey: string | undefined,
  iconMap: Record<string, IconComponent> | undefined,
  fallback: IconComponent
): IconComponent {
  if (iconKey && iconMap?.[iconKey]) return iconMap[iconKey]!
  return fallback
}

// Rows match the Forge menus: 32px, 12px text, the item radius.
const row =
  "flex w-full min-h-8 cursor-default items-center gap-2 rounded-(--radius-item) px-2 py-1.5 text-start text-xs outline-none select-none hover:bg-accent data-[highlighted]:bg-accent data-[highlighted]:text-accent-foreground"

type CategoriesProps = {
  iconMap: Record<string, IconComponent> | undefined
  fallbackIcon: IconComponent
  emptyLabel: string
}

const Categories: FC<CategoriesProps> = ({
  iconMap,
  fallbackIcon,
  emptyLabel,
}) => (
  <ComposerPrimitive.Unstable_TriggerPopoverCategories>
    {(categories) => (
      <div
        data-slot="composer-trigger-popover-categories"
        className="flex flex-col"
      >
        {categories.map((cat) => {
          const Icon = resolveIcon(cat.id, iconMap, fallbackIcon)
          return (
            <ComposerPrimitive.Unstable_TriggerPopoverCategoryItem
              key={cat.id}
              categoryId={cat.id}
              className={cn(row, "justify-between")}
            >
              <span className="flex items-center gap-2">
                <Icon className="size-4 text-muted-foreground" />
                {cat.label}
              </span>
              <ChevronRightIcon className="size-3.5 text-muted-foreground" />
            </ComposerPrimitive.Unstable_TriggerPopoverCategoryItem>
          )
        })}
        {categories.length === 0 && (
          <div className="px-2 py-1.5 text-xs text-muted-foreground">
            {emptyLabel}
          </div>
        )}
      </div>
    )}
  </ComposerPrimitive.Unstable_TriggerPopoverCategories>
)

type ItemsProps = {
  iconMap: Record<string, IconComponent> | undefined
  fallbackIcon: IconComponent
  backLabel: string
  emptyLabel: string
  loadingLabel: string
}

const Items: FC<ItemsProps> = ({
  iconMap,
  fallbackIcon,
  backLabel,
  emptyLabel,
  loadingLabel,
}) => {
  const { isLoading } = unstable_useTriggerPopoverScopeContext()
  return (
    <ComposerPrimitive.Unstable_TriggerPopoverItems>
      {(items) => (
        <div
          data-slot="composer-trigger-popover-items"
          className="flex flex-col"
        >
          <ComposerPrimitive.Unstable_TriggerPopoverBack
            className={cn(row, "gap-1 text-2xs text-muted-foreground")}
          >
            <ChevronLeftIcon className="size-3.5" />
            {backLabel}
          </ComposerPrimitive.Unstable_TriggerPopoverBack>

          {items.map((item, index) => {
            const iconKey =
              typeof item.metadata?.icon === "string"
                ? item.metadata.icon
                : undefined
            const Icon = resolveIcon(iconKey, iconMap, fallbackIcon)
            return (
              <ComposerPrimitive.Unstable_TriggerPopoverItem
                key={item.id}
                item={item}
                index={index}
                className={cn(row, "items-start")}
              >
                <Icon className="mt-px size-4 shrink-0 text-muted-foreground" />
                <span className="flex min-w-0 flex-col gap-0.5">
                  <span className="font-mono text-foreground">
                    {item.label}
                  </span>
                  {item.description && (
                    <span className="text-2xs text-muted-foreground">
                      {item.description}
                    </span>
                  )}
                </span>
              </ComposerPrimitive.Unstable_TriggerPopoverItem>
            )
          })}
          {items.length === 0 && (
            <div className="px-2 py-1.5 text-xs text-muted-foreground">
              {isLoading ? loadingLabel : emptyLabel}
            </div>
          )}
        </div>
      )}
    </ComposerPrimitive.Unstable_TriggerPopoverItems>
  )
}

/**
 * Pre-built popover UI for a trigger-driven picker (mentions, slash commands, etc).
 * Pass exactly one of `directive` (inserts a chip) or `action` (fires a handler).
 */
const ComposerTriggerPopoverImpl: FC<ComposerTriggerPopoverProps> = ({
  iconMap,
  fallbackIcon = SparklesIcon,
  backLabel = "Back",
  emptyCategoriesLabel = "No items available",
  emptyItemsLabel = "No matching items",
  loadingLabel = "Loading…",
  className,
  directive,
  action,
  ...props
}) => {
  return (
    <ComposerPrimitive.Unstable_TriggerPopover
      data-slot="composer-trigger-popover"
      className={cn(
        "aui-composer-trigger-popover absolute start-0 bottom-full z-50 mb-2 max-h-72 w-72 overflow-y-auto rounded-(--radius-band) border border-border bg-popover p-1 text-popover-foreground shadow-lg",
        className
      )}
      {...props}
    >
      {directive ? (
        <ComposerPrimitive.Unstable_TriggerPopover.Directive
          formatter={directive.formatter ?? unstable_defaultDirectiveFormatter}
          onInserted={directive.onInserted}
        />
      ) : action ? (
        <ComposerPrimitive.Unstable_TriggerPopover.Action
          formatter={action.formatter ?? unstable_defaultDirectiveFormatter}
          onExecute={action.onExecute}
          removeOnExecute={action.removeOnExecute}
        />
      ) : null}
      <Categories
        iconMap={iconMap}
        fallbackIcon={fallbackIcon}
        emptyLabel={emptyCategoriesLabel}
      />
      <Items
        iconMap={iconMap}
        fallbackIcon={fallbackIcon}
        backLabel={backLabel}
        emptyLabel={emptyItemsLabel}
        loadingLabel={loadingLabel}
      />
    </ComposerPrimitive.Unstable_TriggerPopover>
  )
}
ComposerTriggerPopoverImpl.displayName = "ComposerTriggerPopover"

export const ComposerTriggerPopover = memo(
  ComposerTriggerPopoverImpl
) as FC<ComposerTriggerPopoverProps>

"use client"

import { memo, type FC } from "react"
import { cva, type VariantProps } from "class-variance-authority"
import {
  FileIcon,
  FileTextIcon,
  ImageIcon,
  MusicIcon,
  VideoIcon,
  BracesIcon,
  DownloadIcon,
} from "@/components/assistant-ui/elements/aui-icons"
import type { FileMessagePartComponent } from "@assistant-ui/react"
import { cn } from "cn"

const fileVariants = cva(
  "aui-file-root inline-flex items-center gap-3 rounded-(--radius-card) transition-colors",
  {
    variants: {
      variant: {
        outline: "border border-border hover:bg-muted/50",
        ghost: "hover:bg-muted/50",
        muted: "bg-muted/50 hover:bg-muted/70",
      },
      size: {
        sm: "px-2.5 py-1.5 text-xs",
        default: "px-3 py-2 text-sm",
        lg: "px-4 py-3 text-sm",
      },
    },
    defaultVariants: {
      variant: "outline",
      size: "default",
    },
  }
)

function getMimeTypeIcon(mimeType: string): FC<{ className?: string }> {
  const type = mimeType.toLowerCase()
  if (type.startsWith("image/")) {
    return ImageIcon
  }
  if (type === "application/pdf") {
    return FileTextIcon
  }
  if (type === "application/json") {
    return BracesIcon
  }
  if (type.startsWith("text/")) {
    return FileTextIcon
  }
  if (type.startsWith("audio/")) {
    return MusicIcon
  }
  if (type.startsWith("video/")) {
    return VideoIcon
  }
  return FileIcon
}

export type FileDataKind = "data-uri" | "url" | "base64" | "id"

function getFileDataKind(
  data: string,
  sourceType?: "url" | "id"
): FileDataKind {
  if (sourceType === "url" && /^data:/i.test(data)) return "data-uri"
  if (sourceType) return sourceType
  if (/^data:/i.test(data)) return "data-uri"
  if (/^https?:\/\//i.test(data)) return "url"
  return "base64"
}

function getBase64PayloadSize(payload: string): number {
  const padding = payload.endsWith("==") ? 2 : payload.endsWith("=") ? 1 : 0
  const firstNonBase64 = payload.search(/[^A-Za-z\d+/]/)
  if (
    (firstNonBase64 !== -1 && firstNonBase64 !== payload.length - padding) ||
    payload.length % 4 === 1 ||
    (padding > 0 && payload.length % 4 !== 0)
  ) {
    return 0
  }
  return Math.floor((payload.length * 3) / 4) - padding
}

function getBase64Size(base64: string): number {
  const payload = /[\t\n\f\r ]/.test(base64)
    ? base64.replace(/[\t\n\f\r ]/g, "")
    : base64
  return getBase64PayloadSize(payload)
}

function getDataUrlSize(data: string): number {
  const fragment = data.indexOf("#")
  const end = fragment < 0 ? data.length : fragment
  const comma = data.indexOf(",")
  if (comma < 0 || comma >= end) {
    return 0
  }
  let payload = data.slice(comma + 1, end)
  if (/;base64$/i.test(data.slice(0, comma))) {
    if (/[%\t\n\f\r ]/.test(payload)) {
      payload = payload
        .replace(/%([\da-f]{2})/gi, (_match, hex: string) =>
          String.fromCharCode(Number.parseInt(hex, 16))
        )
        .replace(/[\t\n\f\r ]/g, "")
    }
    return getBase64PayloadSize(payload)
  }

  // Each percent escape is one byte, including octets that are not valid UTF-8.
  return new TextEncoder().encode(payload.replace(/%[\da-f]{2}/gi, "_"))
    .byteLength
}

function formatFileSize(bytes: number): string {
  if (bytes < 1024) {
    return `${bytes} B`
  }
  if (bytes < 1024 * 1024) {
    return `${(bytes / 1024).toFixed(1)} KB`
  }
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`
}

export type FileRootProps = React.ComponentProps<"div"> &
  VariantProps<typeof fileVariants>

function FileRoot({
  className,
  variant,
  size,
  children,
  ...props
}: FileRootProps) {
  return (
    <div
      data-slot="file-root"
      data-variant={variant}
      data-size={size}
      className={cn(fileVariants({ variant, size, className }))}
      {...props}
    >
      {children}
    </div>
  )
}

type FileIconDisplayProps = React.ComponentProps<"span"> & {
  mimeType?: string
}

function FileIconDisplay({
  mimeType,
  className,
  children,
  ...props
}: FileIconDisplayProps) {
  const IconComponent = mimeType ? getMimeTypeIcon(mimeType) : FileIcon

  return (
    <span
      data-slot="file-icon"
      className={cn("shrink-0 text-muted-foreground", className)}
      {...props}
    >
      {/* eslint-disable-next-line react-hooks/static-components -- The helper only selects module-level icon components. */}
      {children ?? <IconComponent className="size-5" />}
    </span>
  )
}

function FileName({
  className,
  children,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="file-name"
      className={cn("min-w-0 flex-1 truncate font-medium", className)}
      {...props}
    >
      {children || "Unnamed file"}
    </span>
  )
}

type FileSizeProps = React.ComponentProps<"span"> & {
  bytes: number
}

function FileSize({ bytes, className, ...props }: FileSizeProps) {
  return (
    <span
      data-slot="file-size"
      className={cn("shrink-0 text-muted-foreground", className)}
      {...props}
    >
      {formatFileSize(bytes)}
    </span>
  )
}

type FileDownloadProps = Omit<React.ComponentProps<"a">, "href"> & {
  data: string
  mimeType: string
  filename?: string
  sourceType?: "url" | "id"
}

function FileDownload({
  data,
  mimeType,
  filename,
  sourceType,
  className,
  children,
  ...props
}: FileDownloadProps) {
  if (typeof data !== "string") return null
  const kind = getFileDataKind(data, sourceType)
  if (kind === "id") return null
  if (kind === "url" && !/^(https?:\/\/|blob:)/i.test(data)) return null
  const href = kind === "base64" ? `data:${mimeType};base64,${data}` : data

  return (
    <a
      data-slot="file-download"
      href={href}
      download={filename || "download"}
      {...(kind === "url" && { target: "_blank", rel: "noopener noreferrer" })}
      className={cn(
        "shrink-0 rounded-md p-1 text-muted-foreground transition-colors hover:bg-accent hover:text-accent-foreground",
        className
      )}
      aria-label={!children ? `Download ${filename || "file"}` : undefined}
      {...props}
    >
      {children || <DownloadIcon className="size-4" />}
    </a>
  )
}

const FileImpl: FileMessagePartComponent = ({
  filename,
  data,
  mimeType,
  sourceType,
}) => {
  const kind = getFileDataKind(data, sourceType)
  const showSize =
    typeof data === "string" && (kind === "base64" || kind === "data-uri")

  return (
    <FileRoot>
      <FileIconDisplay mimeType={mimeType} />
      <div className="flex min-w-0 flex-1 flex-col gap-0.5">
        <FileName>{filename}</FileName>
        {showSize && (
          <FileSize
            bytes={
              kind === "data-uri" ? getDataUrlSize(data) : getBase64Size(data)
            }
            className="text-xs"
          />
        )}
      </div>
      <FileDownload
        data={data}
        mimeType={mimeType}
        {...(filename !== undefined && { filename })}
        {...(sourceType !== undefined && { sourceType })}
      />
    </FileRoot>
  )
}

const File = memo(FileImpl) as unknown as FileMessagePartComponent & {
  Root: typeof FileRoot
  Icon: typeof FileIconDisplay
  Name: typeof FileName
  Size: typeof FileSize
  Download: typeof FileDownload
}

File.displayName = "File"
File.Root = FileRoot
File.Icon = FileIconDisplay
File.Name = FileName
File.Size = FileSize
File.Download = FileDownload

export {
  File,
  FileRoot,
  FileIconDisplay,
  FileName,
  FileSize,
  FileDownload,
  fileVariants,
  getMimeTypeIcon,
  getFileDataKind,
  getBase64Size,
  formatFileSize,
}

"use client"

import { AuiIf, useAuiState, ThreadPrimitive } from "@assistant-ui/react"
import { useCallback, useEffect, useRef, useState, type FC } from "react"

type FollowupSuggestion = {
  prompt: string
  title?: string | undefined
  label?: string | undefined
}

/**
 * A scrolling row of suggestion chips that send their prompt: the runtime's
 * suggestions, or `suggestions` when given (e.g. ones a server wrote).
 */
export const FollowupSuggestionsRow: FC<{
  suggestions?: readonly FollowupSuggestion[] | undefined
}> = ({ suggestions: given }) => {
  const runtime = useAuiState((s) => s.thread.suggestions)
  const suggestions: readonly FollowupSuggestion[] = given ?? runtime
  const scrollRef = useRef<HTMLDivElement>(null)
  const rtlRef = useRef<boolean | null>(null)
  const [fades, setFades] = useState({ left: false, right: false })

  const updateFades = useCallback(() => {
    const el = scrollRef.current
    if (!el) return
    const maxScroll = el.scrollWidth - el.clientWidth
    // scrollLeft runs 0..-max in RTL; normalize to hidden width per physical edge.
    const fromStart = Math.abs(el.scrollLeft)
    // getComputedStyle forces a style recalc per scroll event; direction is stable, read it once.
    const rtl = (rtlRef.current ??= getComputedStyle(el).direction === "rtl")
    const [left, right] = rtl
      ? [maxScroll - fromStart, fromStart]
      : [fromStart, maxScroll - fromStart]
    setFades((prev) => {
      const next = { left: left > 1, right: right > 1 }
      return prev.left === next.left && prev.right === next.right ? prev : next
    })
  }, [])

  useEffect(() => {
    updateFades()
    const el = scrollRef.current
    if (!el?.firstElementChild) return undefined
    const observer = new ResizeObserver(updateFades)
    observer.observe(el)
    observer.observe(el.firstElementChild)
    return () => observer.disconnect()
  }, [updateFades])

  const maskImage = `linear-gradient(to right, ${
    fades.left ? "transparent, black 2rem" : "black"
  }, ${fades.right ? "black calc(100% - 2rem), transparent" : "black"})`

  return (
    <div
      ref={scrollRef}
      onScroll={updateFades}
      // overflow-x clips both axes; py-1/-my-1 gives focus rings vertical room without changing outer height.
      className="aui-thread-followup-suggestions -my-1 w-full [scrollbar-width:none] overflow-x-auto py-1 [-ms-overflow-style:none] [&::-webkit-scrollbar]:hidden"
      style={{ maskImage, WebkitMaskImage: maskImage }}
    >
      <div className="mx-auto flex min-h-8 w-max items-center gap-2 px-0.5">
        {suggestions.map((suggestion, idx) => (
          <ThreadPrimitive.Suggestion
            key={idx}
            className="aui-thread-followup-suggestion rounded-(--radius-control) border border-border px-2.5 py-1 text-xs whitespace-nowrap transition-colors ease-in hover:border-foreground/25 hover:bg-foreground/[0.03] motion-reduce:transition-none"
            prompt={suggestion.prompt}
            send
          >
            {suggestion.title ?? suggestion.prompt}
            {suggestion.label && (
              <span className="aui-thread-followup-suggestion-label ms-1 text-muted-foreground">
                {suggestion.label}
              </span>
            )}
          </ThreadPrimitive.Suggestion>
        ))}
      </div>
    </div>
  )
}

