function ImagePreview({
  className,
  containerClassName,
  onLoad,
  onError,
  alt = "Image content",
  src,
  ...props
}: ImagePreviewProps) {
  const imgRef = useRef<HTMLImageElement>(null)
  const [loadedSrc, setLoadedSrc] = useState<string | undefined>(undefined)
  const [errorSrc, setErrorSrc] = useState<string | undefined>(undefined)

  const loaded = loadedSrc === src
  const error = errorSrc === src

  useEffect(() => {
    const image = imgRef.current
    if (typeof src !== "string" || !image?.complete) return
    if (image.naturalWidth > 0) setLoadedSrc(src)
    else setErrorSrc(src)
  }, [src])

  return (
    <div
      data-slot="image-preview"
      className={cn("relative min-h-32", containerClassName)}
    >
      {!loaded && !error && (
        <div
          data-slot="image-preview-loading"
          className="absolute inset-0 flex items-center justify-center bg-muted/50"
        >
          <ImageIcon className="size-8 animate-pulse text-muted-foreground" />
        </div>
      )}
      {error ? (
        <div
          data-slot="image-preview-error"
          className="flex min-h-32 items-center justify-center bg-muted/50 p-4"
        >
          <ImageOffIcon className="size-8 text-muted-foreground" />
        </div>
      ) : (
        <img
          ref={imgRef}
          src={src}
          alt={alt}
          className={cn(
            "block h-auto w-full object-contain",
            !loaded && "invisible",
            className
          )}
          onLoad={(e) => {
            if (typeof src === "string") setLoadedSrc(src)
            onLoad?.(e)
          }}
          onError={(e) => {
            if (typeof src === "string") setErrorSrc(src)
            onError?.(e)
          }}
          {...props}
        />
      )}
    </div>
  )
}

