import { useCallback, useEffect, useRef, type RefObject } from "react"

/** Set on the scrolling ancestor while a disclosure animates in it. */
export const DISCLOSURE_HOLD_ATTRIBUTE = "data-disclosure-hold"
// How long held height the thread no longer fills takes to go.
const SETTLE_MS = 180

const scrollableAncestor = (element: HTMLElement) => {
  let current = element.parentElement
  while (current) {
    const { overflowY } = getComputedStyle(current)
    if (overflowY === "scroll" || overflowY === "auto") return current
    current = current.parentElement
  }
  return null
}

type Hold = {
  /** Disclosures animating; nested ones share the hold. */
  count: number
  content: HTMLElement | null
  /** The inline styles to put back. */
  minHeight: string
  overflowAnchor: string
  /** Stops the settling after the last one ended, if it's running. */
  stopSettling?: () => void
}
const holds = new WeakMap<HTMLElement, Hold>()

/**
 * Keeps the scroller from shrinking while a disclosure animates: its content
 * keeps at least its current height, and the browser's scroll anchoring is
 * off. Otherwise a panel closing near the bottom shortens the thread each
 * frame, the browser pulls the scroll position down, and the thread's top
 * anchor (whose spacer catches up a frame later) pushes it back up: the
 * conversation shakes.
 *
 * @returns Releases the hold.
 */
function holdScroller(scroller: HTMLElement) {
  let hold = holds.get(scroller)
  if (hold?.stopSettling) {
    // Still settling from the last one: this one takes the hold over.
    hold.stopSettling()
    hold.stopSettling = undefined
  }
  if (!hold) {
    const content = scroller.firstElementChild as HTMLElement | null
    hold = {
      count: 0,
      content,
      minHeight: content?.style.minHeight ?? "",
      overflowAnchor: scroller.style.overflowAnchor,
    }
    holds.set(scroller, hold)
    scroller.style.overflowAnchor = "none"
    scroller.setAttribute(DISCLOSURE_HOLD_ATTRIBUTE, "")
  }
  if (hold.count === 0 && hold.content) {
    hold.content.style.minHeight = `${hold.content.getBoundingClientRect().height}px`
  }
  hold.count++
  const current = hold
  let released = false
  return () => {
    if (released) return
    released = true
    if (--current.count > 0) return
    const done = () => {
      if (holds.get(scroller) !== current || current.count > 0) return
      holds.delete(scroller)
      if (current.content) current.content.style.minHeight = current.minHeight
      scroller.style.overflowAnchor = current.overflowAnchor
      scroller.removeAttribute(DISCLOSURE_HOLD_ATTRIBUTE)
    }
    const excess = current.content && excessHeight(scroller, current)
    if (excess) current.stopSettling = easeAway(current.content!, excess, done)
    else done()
  }
}

/**
 * How much of the held height the thread no longer fills, when giving it up
 * at once would pull the scroll position down (a panel closed near the
 * bottom of a reply taller than the thread); null when releasing moves
 * nothing, as when the thread's top-anchor spacer has taken the room back.
 * Measured by dropping the hold and putting it back before anything paints.
 */
function excessHeight(scroller: HTMLElement, hold: Hold) {
  const content = hold.content!
  const held = content.style.minHeight
  const top = scroller.scrollTop
  content.style.minHeight = hold.minHeight
  const natural = scroller.scrollHeight
  content.style.minHeight = held
  if (scroller.scrollTop !== top) {
    scroller.scrollTo({ top, behavior: "instant" })
  }
  const bottom = natural - scroller.clientHeight
  const heldHeight = Number.parseFloat(held)
  return top > bottom + 0.5 && Number.isFinite(heldHeight)
    ? { from: heldHeight, to: heldHeight - (top - bottom) }
    : null
}

/**
 * Gives up held height over a moment instead of at once, so what's above
 * the closed panel settles down smoothly rather than jumping.
 *
 * @returns Stops it where it is, without finishing.
 */
function easeAway(
  content: HTMLElement,
  { from, to }: { from: number; to: number },
  done: () => void
) {
  const start = performance.now()
  let frame = 0
  const step = () => {
    const progress = Math.min(1, (performance.now() - start) / SETTLE_MS)
    const eased = 1 - (1 - progress) ** 3
    content.style.minHeight = `${from + (to - from) * eased}px`
    if (progress < 1) frame = requestAnimationFrame(step)
    else finish()
  }
  // Frames don't run in a hidden tab; it still settles.
  const timeout = setTimeout(() => finish(), SETTLE_MS + 200)
  const stop = () => {
    cancelAnimationFrame(frame)
    clearTimeout(timeout)
  }
  const finish = () => {
    stop()
    done()
  }
  frame = requestAnimationFrame(step)
  return stop
}

/**
 * Keeps a disclosure (reasoning, a tool call, a group of them) where it is
 * on screen while it opens or closes, so what was clicked stays under the
 * pointer and nothing around it jumps:
 *
 * - The thread can't get shorter during the animation (`holdScroller`);
 *   room it no longer fills afterwards goes smoothly.
 * - Each frame, it scrolls by however far the disclosure moved, instantly.
 * - The thread's reply following (`useFollowReply`) waits until it's done
 *   (`data-disclosure-hold` on the scroller).
 *
 * It replaces assistant-ui's `useScrollLock`, which hides the scrollbar for
 * the animation: the thread reserves the scrollbar's gutter on both edges
 * (`scrollbar-gutter: stable both-edges`), so hiding it moved the whole
 * conversation sideways and back on every toggle.
 *
 * @param ref The disclosure.
 * @param duration How long its animation runs, in milliseconds.
 * @returns Call it right before the disclosure opens or closes.
 */
export function useDisclosureAnchor(
  ref: RefObject<HTMLElement | null>,
  duration: number
) {
  const stop = useRef<(() => void) | null>(null)
  useEffect(() => () => stop.current?.(), [])

  return useCallback(() => {
    stop.current?.()
    const element = ref.current
    const scroller = element && scrollableAncestor(element)
    if (!element || !scroller) {
      stop.current = null
      return
    }
    const release = holdScroller(scroller)
    const start = element.getBoundingClientRect().top
    // One frame past the animation, for its last step.
    const end = performance.now() + duration + 20
    let frame = 0
    const finish = () => {
      cancelAnimationFrame(frame)
      clearTimeout(timeout)
      release()
      stop.current = null
    }
    // Frames don't run in a hidden tab; the hold still ends.
    const timeout = setTimeout(finish, duration + 200)
    const hold = () => {
      const drift = element.getBoundingClientRect().top - start
      if (Math.abs(drift) >= 0.5) {
        scroller.scrollBy({ top: drift, behavior: "instant" })
      }
      if (performance.now() < end) frame = requestAnimationFrame(hold)
      else finish()
    }
    frame = requestAnimationFrame(hold)
    stop.current = finish
  }, [ref, duration])
}

import { useEffect, useRef, type RefObject } from "react"
import { useAuiState } from "@assistant-ui/react"

import { DISCLOSURE_HOLD_ATTRIBUTE } from "./use-disclosure-anchor"

// Pixels from the bottom that still count as at the bottom.
const AT_BOTTOM = 2
// Pixels below the viewport's top that still count as pinned there.
const PINNED = 24
// How long assistant-ui gets to scroll a new question to the top.
const PIN_MS = 1500
// How long after a run ends its last text and the reply's action bar are
// still followed: they arrive with the end of the run.
const SETTLE_MS = 1500
// How long after a wheel, touch or key a scroll counts as the person's.
const INPUT_MS = 500
const SCROLL_KEYS = new Set([
  "ArrowUp",
  "ArrowDown",
  "PageUp",
  "PageDown",
  "Home",
  "End",
  " ",
])
const TEXT_ENTRY = "textarea, input, select, [contenteditable]"

/**
 * Keeps a streaming reply's newest text in view once the reply fills the
 * viewport.
 *
 * With `turnAnchor="top"`, sending a message scrolls it to the top and
 * reserves the rest of the viewport for the reply (an empty spacer after it,
 * `data-aui-top-anchor-reserve`), but assistant-ui never scrolls while the
 * reply streams, so a long one runs on below the fold. Once the question is
 * pinned and the reply has used up the spacer, this follows the bottom as it
 * grows, until shortly after the run ends; should the reply shrink again
 * (its reasoning folding away), following the bottom returns to the pinned
 * question. Scrolling up to read stops it, and so does opening or closing
 * the reasoning or a tool call (they're reading it, and it holds itself in
 * place: `useDisclosureAnchor`); getting back to the bottom (scrolling, or
 * the scroll-to-bottom button) starts it again.
 *
 * @param viewportRef The thread's `ThreadPrimitive.Viewport`.
 */
export function useFollowReply(viewportRef: RefObject<HTMLElement | null>) {
  const isRunning = useAuiState((s) => s.thread.isRunning)
  // Shared with the listeners below, which live as long as the viewport.
  const follow = useRef({
    following: false,
    started: 0,
    until: 0,
    followed: false,
  })

  // Each run arms it, until a moment after the run ends.
  useEffect(() => {
    if (isRunning) {
      follow.current = {
        following: true,
        started: performance.now(),
        until: Number.POSITIVE_INFINITY,
        followed: false,
      }
    } else {
      follow.current.until = performance.now() + SETTLE_MS
    }
  }, [isRunning])

  useEffect(() => {
    const viewport = viewportRef.current
    const content = viewport?.firstElementChild
    if (!viewport || !content) return

    const belowFold = () =>
      viewport.scrollHeight - viewport.clientHeight - viewport.scrollTop
    // Whether assistant-ui is still scrolling the new question to the top.
    // Until it's there, the bottom is below it; once it is, the bottom is
    // the pinned position for as long as the spacer holds room for the reply.
    const pinning = () => {
      if (performance.now() - follow.current.started > PIN_MS) return false
      const questions = viewport.querySelectorAll('[data-role="user"]')
      const question = questions[questions.length - 1]
      if (!question) return false
      const top = question.getBoundingClientRect().top
      return top - viewport.getBoundingClientRect().top > PINNED
    }

    const onResize = () => {
      const state = follow.current
      if (!state.following || performance.now() > state.until) return
      if (belowFold() <= AT_BOTTOM || (!state.followed && pinning())) return
      state.followed = true
      viewport.scrollTo({ top: viewport.scrollHeight, behavior: "instant" })
    }
    // Following stops only when the thread itself moves up because of the
    // person: a wheel over a panel that scrolls on its own (the reasoning, a
    // code block) doesn't move it, and a reply that shrinks moves it without
    // them.
    let lastTop = viewport.scrollTop
    let inputAt = Number.NEGATIVE_INFINITY
    let dragging = false
    const onInput = () => {
      inputAt = performance.now()
    }
    const onScroll = () => {
      const top = viewport.scrollTop
      // A disclosure holding itself in place scrolls; that isn't a return to
      // the bottom.
      if (viewport.hasAttribute(DISCLOSURE_HOLD_ATTRIBUTE)) {
        lastTop = top
        return
      }
      const byPerson = dragging || performance.now() - inputAt < INPUT_MS
      if (byPerson && top < lastTop - 1) follow.current.following = false
      else if (belowFold() <= AT_BOTTOM) follow.current.following = true
      lastTop = top
    }
    const onKeyDown = (event: KeyboardEvent) => {
      const target = event.target as Element | null
      if (SCROLL_KEYS.has(event.key) && !target?.closest(TEXT_ENTRY)) onInput()
    }
    // A press on the viewport itself, not its content, is on the scrollbar.
    const onPointerDown = (event: PointerEvent) => {
      if (event.target === viewport) dragging = true
    }
    const onPointerUp = () => {
      dragging = false
    }

    const resize = new ResizeObserver(onResize)
    resize.observe(content)
    // Opening or closing the reasoning or a tool call stops following.
    const disclosure = new MutationObserver(() => {
      if (viewport.hasAttribute(DISCLOSURE_HOLD_ATTRIBUTE)) {
        follow.current.following = false
      }
    })
    disclosure.observe(viewport, {
      attributes: true,
      attributeFilter: [DISCLOSURE_HOLD_ATTRIBUTE],
    })
    viewport.addEventListener("scroll", onScroll, { passive: true })
    viewport.addEventListener("wheel", onInput, { passive: true })
    viewport.addEventListener("touchmove", onInput, { passive: true })
    viewport.addEventListener("keydown", onKeyDown)
    viewport.addEventListener("pointerdown", onPointerDown)
    window.addEventListener("pointerup", onPointerUp)
    return () => {
      resize.disconnect()
      disclosure.disconnect()
      viewport.removeEventListener("scroll", onScroll)
      viewport.removeEventListener("wheel", onInput)
      viewport.removeEventListener("touchmove", onInput)
      viewport.removeEventListener("keydown", onKeyDown)
      viewport.removeEventListener("pointerdown", onPointerDown)
      window.removeEventListener("pointerup", onPointerUp)
    }
  }, [viewportRef])
}

import { useEffect, useSyncExternalStore } from "react"
import { useAuiState } from "@assistant-ui/react"

// When each reasoning block started and how long it took, by message and
// first part, for as long as the page is open: switching conversations and
// back keeps them. Replies loaded from history weren't timed here.
const reasoningTimes = new Map<string, { start: number; seconds?: number }>()
const timeListeners = new Set<() => void>()
const subscribeToTimes = (listener: () => void) => {
  timeListeners.add(listener)
  return () => {
    timeListeners.delete(listener)
  }
}
// A question asked longer ago than this didn't start the thinking, e.g. a
// run resumed after an approval.
const MAX_WAIT_MS = 5 * 60_000

/**
 * How long a reasoning block of the current message took, in whole seconds
 * (at least 1): until its last thought streamed, from the question for a
 * reply's first thoughts (the model thinks before its first thought
 * arrives), or from its first thought for later ones (after tool calls).
 * Undefined while it runs, and for blocks this page didn't see stream.
 *
 * @param firstIndex The index of the block's first part in the message.
 * @param running Whether it's still streaming.
 */
export function useReasoningDuration(firstIndex: number, running: boolean) {
  const key = useAuiState((s) => `${s.message.id}:${firstIndex}`)
  const asked = useAuiState((s) => {
    if (firstIndex !== 0) return undefined
    for (let index = s.message.index - 1; index >= 0; index--) {
      const message = s.thread.messages[index]
      if (message?.role === "user") return message.createdAt.getTime()
    }
    return undefined
  })

  useEffect(() => {
    const time = reasoningTimes.get(key)
    if (running) {
      if (!time) {
        const now = Date.now()
        const recent = asked !== undefined && now - asked < MAX_WAIT_MS
        reasoningTimes.set(key, { start: recent ? asked : now })
      }
      return
    }
    if (time && time.seconds === undefined) {
      time.seconds = Math.max(1, Math.round((Date.now() - time.start) / 1000))
      timeListeners.forEach((listener) => listener())
    }
  }, [key, running, asked])

  return useSyncExternalStore(
    subscribeToTimes,
    () => reasoningTimes.get(key)?.seconds
  )
}

"use client"

import { useEffect, useState } from "react"
import { useAuiState } from "@assistant-ui/react"
import { useShallow } from "zustand/react/shallow"

const useFileSrc = (file: File | undefined) => {
  const [entry, setEntry] = useState<{ file: File; url: string } | undefined>(
    undefined
  )

  useEffect(() => {
    // The object URL is a browser resource whose lifetime has to straddle
    // commit, so allocation, revocation, and clearing the entry that names a
    // revoked URL all belong to the effect.
    if (!file) {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setEntry(undefined)
      return
    }

    const objectUrl = URL.createObjectURL(file)
    setEntry({ file, url: objectUrl })

    return () => {
      URL.revokeObjectURL(objectUrl)
    }
  }, [file])

  return entry !== undefined && entry.file === file ? entry.url : undefined
}

export const useAttachmentSrc = () => {
  const { file, src } = useAuiState(
    useShallow((s): { file?: File; src?: string } => {
      if (s.attachment.type !== "image") return {}
      if (s.attachment.file) return { file: s.attachment.file }
      const src = s.attachment.content?.filter((c) => c.type === "image")[0]
        ?.image
      if (!src) return {}
      return { src }
    })
  )

  return useFileSrc(file) ?? src
}

"use client"

import { useEffect, useRef, useState } from "react"

export type UseCopyToClipboardOptions = {
  copiedDuration?: number
}

export const useCopyToClipboard = ({
  copiedDuration = 3000,
}: UseCopyToClipboardOptions = {}) => {
  const [isCopied, setIsCopied] = useState<boolean>(false)
  const copiedTimerRef = useRef<ReturnType<typeof setTimeout> | undefined>(
    undefined
  )
  const scopeGenerationRef = useRef(0)

  useEffect(
    () => () => {
      scopeGenerationRef.current += 1
      if (copiedTimerRef.current === undefined) return

      clearTimeout(copiedTimerRef.current)
      copiedTimerRef.current = undefined
      setIsCopied(false)
    },
    []
  )

  const copyToClipboard = (value: string) => {
    if (!value || typeof navigator === "undefined" || !navigator.clipboard) {
      return
    }

    const scopeGeneration = scopeGenerationRef.current
    navigator.clipboard.writeText(value).then(
      () => {
        if (scopeGeneration !== scopeGenerationRef.current) return

        if (copiedTimerRef.current !== undefined) {
          clearTimeout(copiedTimerRef.current)
        }
        setIsCopied(true)
        copiedTimerRef.current = setTimeout(() => {
          copiedTimerRef.current = undefined
          setIsCopied(false)
        }, copiedDuration)
      },
      () => {}
    )
  }

  return { isCopied, copyToClipboard }
}
